-- =====================================================================
--  行政区划基础信息（sys_region）种子数据：省 34 + 市 342 + 区县 3056 = 3432 行
--
--  依据：docs/REQ-地区基础信息与区域筛选下拉.md
--
--  数据来源：国标 GB/T 2260 行政区划（三级全量）。
--    数据集：modood/Administrative-divisions-of-China 的 pca-code.json（省 31 / 市 342 / 区县 3056），
--    代码按国标补零到 6 位（省 2 位补 0000、市 4 位补 00、区县本就是 6 位），并手工补入
--    GB/T 2260 的港澳台三个省级单位（710000/810000/820000，国标中无下级）。
--    ⚠️ 省名必须是**全称**且与既有业务数据的 region_name 逐字一致（浙江省 / 江苏省 / …），
--       否则订单列表里的地区列会和筛选下拉的显示名对不上。
--
--  幂等：INSERT IGNORE（主键 code）。刻意不用 ON DUPLICATE KEY UPDATE ——
--    ① 人工改过的名称/状态不会被每次启动覆盖回去；
--    ② 被逻辑删除的地区不会因为重启而"复活"。
--    代价：日后修正国标名称需要显式 UPDATE（见本文件末尾的示例）。
--
--  执行方式：由 Spring Boot 在启动时自动执行（application.yml 的
--    spring.sql.init.data-locations 指向本文件，mode=always），
--    新库与存量库走同一条路径，因此**不需要** db/migration/V7 手工脚本。
-- =====================================================================

